-- 44 Garden Party: tells forty guests where to go. How they get there -
-- round hedges, beds, tables and the fountain, past one another, into a
-- loose crowd when called - is the engine's navigation (`nav_region` on the
-- lawn, `nav_agent` on each guest). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/44-garden-party.scene"
local GUESTS = 40
local DOTS = 28
local GATE_SHUT, GATE_OPEN = -460.0, -400.0
local SPOTS = {
    { -470.0, 0.0 },
    { -560.0, 150.0 },
    { -380.0, 160.0 },
    { -560.0, -150.0 },
    { -390.0, -155.0 },
    { 150.0, 0.0 },
    { 106.1, 106.1 },
    { 0.0, 150.0 },
    { -106.1, 106.1 },
    { -150.0, 0.0 },
    { -106.1, -106.1 },
    { -0.0, -150.0 },
    { 106.1, -106.1 },
    { 320.0, 70.0 },
    { 440.0, 0.0 },
    { 560.0, 140.0 },
    { 330.0, 210.0 },
    { 255.0, -75.0 },
    { 330.0, -200.0 },
    { 480.0, -170.0 },
    { 545.0, -150.0 },
    { -200.0, 280.0 },
    { 60.0, 300.0 },
    { -230.0, -270.0 },
    { 200.0, -280.0 },
    { -250.0, 30.0 },
    { 560.0, 290.0 }
}
local post_on = nav.post_all_on(SCENE)
local captions = true
local guests, wait, dots = {}, {}, {}
local ring, gate, gathering, status
local gate_shut = false
local toast = 0
local host_goal = nil

function init(entity)
    for i = 1, GUESTS do
        guests[i] = Entity.find_by_name("Guest" .. i)
        wait[i] = math.random() * 3
        if guests[i] then Nav.set(guests[i], "speed", 55 + math.random() * 35) end
    end
    for i = 1, DOTS do dots[i] = Entity.find_by_name("Petal" .. i) end
    ring = Entity.find_by_name("HostRing")
    gate = Entity.find_by_name("Gate")
    gathering = Entity.find_by_name("Gathering")
    status = Entity.find_by_name("Status")
end

local function wander(i)
    local s = SPOTS[math.random(#SPOTS)]
    local x, y = s[1] + (math.random() - 0.5) * 50, s[2] + (math.random() - 0.5) * 50
    Nav.set_target(guests[i], x, y)
    if i == 1 then host_goal = { x, y } end
end

-- The host's way, as petals spread evenly along Nav.find_path.
local function draw_way(hx, hy, show)
    local path = show and host_goal and Nav.find_path(hx, hy, host_goal[1], host_goal[2])
    if not path or #path < 2 then
        for k = 1, DOTS do if dots[k] then Transform.set_position(dots[k], 0, -2000) end end
        return
    end
    local total = 0
    for i = 2, #path do
        total = total + math.sqrt((path[i][1] - path[i - 1][1]) ^ 2 + (path[i][2] - path[i - 1][2]) ^ 2)
    end
    local leg, walked = 2, 0
    for k = 1, DOTS do
        local want = total * k / DOTS
        while leg < #path do
            local l = math.sqrt((path[leg][1] - path[leg - 1][1]) ^ 2 + (path[leg][2] - path[leg - 1][2]) ^ 2)
            if walked + l >= want then break end
            walked = walked + l
            leg = leg + 1
        end
        local a, b = path[leg - 1], path[leg]
        local l = math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2)
        local t = 0
        if l > 0 then t = math.min(1, (want - walked) / l) end
        if dots[k] then Transform.set_position(dots[k], a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t) end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end

    if Input.is_mouse_left_just_pressed() then
        local mx, my = Input.get_mouse_world_position()
        local cx, cy = Nav.closest_point(mx, my)
        if cx then
            for i = 1, GUESTS do if guests[i] then Nav.set_target(guests[i], cx, cy) end end
            host_goal = { cx, cy }
            toast = 9
            if gathering then Transform.set_position(gathering, cx, cy) end
        end
    end
    if Input.is_mouse_right_just_pressed() then
        toast = 0
        for i = 1, GUESTS do wait[i] = math.random() * 1.5 end
    end
    if Input.is_key_just_pressed("G") and gate then
        gate_shut = not gate_shut
        Transform.set_position(gate, gate_shut and GATE_SHUT or GATE_OPEN, 210)
    end

    if toast > 0 then
        toast = toast - dt
        if toast <= 0 then
            for i = 1, GUESTS do wait[i] = math.random() * 4 end
            if gathering then Transform.set_position(gathering, 0, -2000) end
        end
    else
        -- Mingle: a guest who has arrived lingers a while, then wanders on.
        for i = 1, GUESTS do
            local g = guests[i]
            if g then
                if Nav.is_moving(g) then
                    wait[i] = 2 + math.random() * 5
                else
                    wait[i] = wait[i] - dt
                    if wait[i] <= 0 then
                        wander(i)
                        wait[i] = 1
                    end
                end
            end
        end
    end

    local host = guests[1]
    if host then
        local hx, hy = Transform.get_position(host)
        if ring then Transform.set_position(ring, hx, hy) end
        draw_way(hx, hy, Nav.is_moving(host))
    end
    if status then
        local walking = 0
        for i = 1, GUESTS do if guests[i] and Nav.is_moving(guests[i]) then walking = walking + 1 end end
        local what = toast > 0 and "gathering for a toast" or "mingling"
        UI.set_text(status, what .. "  -  " .. walking .. " of " .. GUESTS .. " walking" .. (gate_shut and "  -  gate shut" or ""))
    end
end
